-- BEGIN/ROLLBACK only, no customer stock or financial transfer.
create temporary table fulfillment_qa(label text primary key,passed boolean);
create function pg_temp.qa_fulfillment(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'QA FAILED: %',label;end if;insert into fulfillment_qa values(label,true);end $$;
do $$
declare a uuid:=gen_random_uuid();u uuid:=gen_random_uuid();p uuid:=gen_random_uuid();o uuid;first_item uuid;second_item uuid;replacement uuid;input jsonb;r jsonb;code text;failed boolean;expected bigint;d record;
begin
 insert into auth.users(id,email) values(a,'qa-admin-'||a||'@example.invalid'),(u,'qa-viewer-'||u||'@example.invalid');insert into public.profiles(id,email,role,status) values(a,'qa@example.invalid','super_admin','active'),(u,'qa@example.invalid','viewer','active');
 insert into public.sales_products(id,sku,name,product_type,unit_price_vnd,status,product_group) values(p,'QA-'||p,'QA debt warranty','qa_warranty',100000,'active','fanpage');
 code:='FS'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10));
 input:=jsonb_build_object('order_code',code,'product_id',p,'buyer_user_id',u,'buyer_name','QA','buyer_phone','0000000000','buyer_email','qa@example.invalid','quantity',2,'unit_price_vnd',100000,'gross_amount_vnd',200000,'discount_percent',0,'discount_amount_vnd',0,'promo_discount_vnd',0,'expected_amount_vnd',200000,'payment_reference',code,'referral_code','QA-REF','payment_expires_at',now()+interval '15 minutes');
 select id into o from public.sales_checkout_create(input,'{}');perform pg_temp.qa_fulfillment((select fulfillment_status='page_debt' and referral_code='QA-REF' from public.sales_orders where id=o) and (select count(*)=1 from public.sales_invoice_records where order_id=o),'no stock accepts atomic order invoice and referral');
 failed:=false;begin perform public.sales_order_allocate(a,jsonb_build_object('order_id',o));exception when raise_exception then failed:=true;end;perform pg_temp.qa_fulfillment(failed,'unpaid order not allocated by operator');
 update public.sales_orders set payment_status='paid' where id=o;
 failed:=false;begin perform public.sales_order_allocate(u,jsonb_build_object('order_id',o));exception when raise_exception then if sqlerrm='Forbidden' then failed:=true;else raise;end if;end;perform pg_temp.qa_fulfillment(failed,'owner cannot allocate without scope');
 r:=public.sales_order_allocate(a,jsonb_build_object('order_id',o));perform pg_temp.qa_fulfillment((r->>'missing_quantity')::integer=2,'paid debt without stock preserved');
 r:=public.sales_inventory_command('intake',a,jsonb_build_object('product_id',p,'facebook_page_id','950000000001','page_name','QA first','page_link','https://facebook.com/950000000001','purchase_cost_vnd',45000));first_item:=(r->'item'->>'id')::uuid;perform public.sales_inventory_command('publish',a,jsonb_build_object('inventory_item_id',first_item));r:=public.sales_order_allocate(a,jsonb_build_object('order_id',o));perform pg_temp.qa_fulfillment((r->>'missing_quantity')::integer=1,'partial allocation reports remaining debt');
 r:=public.sales_inventory_command('intake',a,jsonb_build_object('product_id',p,'facebook_page_id','950000000002','page_name','QA second','page_link','https://facebook.com/950000000002','purchase_cost_vnd',40000));second_item:=(r->'item'->>'id')::uuid;perform public.sales_inventory_command('publish',a,jsonb_build_object('inventory_item_id',second_item));r:=public.sales_order_allocate(a,jsonb_build_object('order_id',o));perform pg_temp.qa_fulfillment((r->>'missing_quantity')::integer=0 and (select count(*)=2 from public.sales_order_inventory_items where order_id=o),'allocation fills order with unique Page codes');
 failed:=false;begin perform public.sales_order_finish(a,jsonb_build_object('order_id',o,'action','finalize'));exception when raise_exception then if sqlerrm='Access handover confirmation required' then failed:=true;else raise;end if;end;perform pg_temp.qa_fulfillment(failed,'external access must be explicitly confirmed');
 perform public.sales_order_finish(a,jsonb_build_object('order_id',o,'action','start_handover'));perform pg_temp.qa_fulfillment((select fulfillment_status='granting' from public.sales_orders where id=o),'start handing over stage');
 perform public.sales_order_finish(a,jsonb_build_object('order_id',o,'action','finalize','access_granted',true));r:=public.sales_order_finish(a,jsonb_build_object('order_id',o,'action','finalize','access_granted',true));perform pg_temp.qa_fulfillment((r->>'duplicate')::boolean and (select fulfillment_status='completed' from public.sales_orders where id=o),'finish idempotent after external grant');
 select expected_amount_vnd into expected from public.sales_orders where id=o;
 failed:=false;begin perform public.sales_order_warranty(u,jsonb_build_object('order_id',o,'inventory_item_id',first_item,'reason','QA'));exception when raise_exception then if sqlerrm='Forbidden' then failed:=true;else raise;end if;end;perform pg_temp.qa_fulfillment(failed,'warranty requires capability and order scope');
 r:=public.sales_order_warranty(a,jsonb_build_object('order_id',o,'inventory_item_id',first_item,'reason','QA failed'));perform pg_temp.qa_fulfillment((select status='damaged' from public.sales_inventory_items where id=first_item) and (select fulfillment_status='page_debt' from public.sales_orders where id=o),'warranty marks original damaged and records debt');
 r:=public.sales_order_warranty(a,jsonb_build_object('order_id',o,'inventory_item_id',first_item,'reason','retry'));perform pg_temp.qa_fulfillment((r->>'duplicate')::boolean and (select count(*)=1 and sum(cost_vnd)=45000 and sum(revenue_vnd)=0 from public.sales_inventory_writeoffs where inventory_item_id=first_item),'warranty retry no duplicate expense');
 r:=public.sales_inventory_command('intake',a,jsonb_build_object('product_id',p,'facebook_page_id','950000000003','page_name','QA replacement','page_link','https://facebook.com/950000000003','purchase_cost_vnd',42000));replacement:=(r->'item'->>'id')::uuid;perform public.sales_inventory_command('publish',a,jsonb_build_object('inventory_item_id',replacement));perform public.sales_order_allocate(a,jsonb_build_object('order_id',o));perform public.sales_order_finish(a,jsonb_build_object('order_id',o,'action','finalize','access_granted',true));
 perform pg_temp.qa_fulfillment((select status='completed' and replacement_inventory_item_id=replacement from public.sales_order_warranties where order_id=o) and (select fulfillment_status='completed' and expected_amount_vnd=expected from public.sales_orders where id=o),'replacement attached and finished without revenue change');
 perform public.sales_discount_tier_schedule(a,jsonb_build_object('product_type','qa_warranty','min_quantity',2,'discount_percent',7,'effective_from',now()-interval '1 day','effective_until',now()+interval '1 day'));
 perform public.sales_discount_tier_schedule(a,jsonb_build_object('product_type','qa_warranty','min_quantity',2,'discount_percent',15,'effective_from',now()+interval '2 days'));
 select * into d from public.sales_discount_tiers where product_type='qa_warranty' and effective_from<=now() and (effective_until is null or effective_until>now()) order by effective_from desc limit 1;perform pg_temp.qa_fulfillment(d.discount_percent=7,'future discount does not override current schedule');
 perform pg_temp.qa_fulfillment(not has_function_privilege('authenticated','public.sales_order_warranty(uuid,jsonb)','EXECUTE'),'warranty RPC not callable by clients');
end $$;
select * from fulfillment_qa order by label;
